['views.css','light.css'].forEach(href=>{const link=document.createElement('link');link.rel='stylesheet';link.href='./'+href;document.head.append(link)});const drawer=document.querySelector('.drawer'),scrim=document.querySelector('.scrim'),themeToggle=document.querySelector('.theme-toggle'),main=document.querySelector('main'),home=[...main.children].filter(x=>!x.classList.contains('topbar'));function open(){drawer.classList.add('open');scrim.classList.add('open')}function close(){drawer.classList.remove('open');scrim.classList.remove('open')}document.querySelectorAll('.issue').forEach(x=>x.onclick=()=>{document.querySelectorAll('.issue').forEach(i=>i.classList.remove('active'));x.classList.add('active');open()});document.querySelector('.close').onclick=close;scrim.onclick=close;document.onkeydown=e=>e.key==='Escape'&&close();const saved=localStorage.getItem('dk-theme')||(matchMedia('(prefers-color-scheme:light)').matches?'light':'dark');document.documentElement.dataset.theme=saved;themeToggle.onclick=()=>{const n=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=n;localStorage.setItem('dk-theme',n)};fetch('./views.html').then(r=>r.text()).then(html=>{main.insertAdjacentHTML('beforeend',html);const views=[...document.querySelectorAll('.product-view')],nav=[...document.querySelectorAll('nav a')].slice(0,4),titles=['操作中心','飞轮运行','知识','图谱探索'];nav.forEach((a,i)=>a.onclick=()=>{nav.forEach(n=>n.classList.remove('active'));a.classList.add('active');home.forEach(x=>x.style.display=i?'none':'');views.forEach((v,j)=>v.classList.toggle('show',j===i-1));document.querySelector('.topbar h1').textContent=titles[i]})});
